// Set up bounded job with provenance
const workflowId = 'worldbank-v2';
const sourceId = 'src_worldbank';
const publisher = 'World Bank';
const product = 'ops';
const tenantId = 'shared';
const workspaceId = 'shared';

// Generate deterministic event_id based on execution
const eventId = `worldbank_${Date.now()}_${$execution.id}`;

return [{
  json: {
    workflow_id: workflowId,
    source_id: sourceId,
    publisher: publisher,
    product: product,
    tenant_id: tenantId,
    workspace_id: workspaceId,
    event_id: eventId,
    captured_at: new Date().toISOString(),
    provenance: {
      source: 'World Bank Open Data API',
      api_version: 'v2',
      endpoint: 'https://api.worldbank.org/v2',
      indicators: ['SP.POP.TOTL'],
      years: '2019:2025',
      pagination: {
        strategy: 'page_by_page',
        page_size: 1000,
        max_pages: 5
      },
      spider_concurrency: 25,
      proxy_used: true,
      proxy_type: 'webshare_residential'
    }
  }
}];

// Process countries and prepare indicator queries
const countries = $input.all();
const results = [];

// World Bank indicators to fetch
const indicators = ['SP.POP.TOTL', 'NY.GDP.MKTP.CD', 'EG.USE.COMM.FO.ZS'];

countries.forEach(country => {
  indicators.forEach(indicator => {
    results.push({
      json: {
        country_code: country.json.iso2Code,
        country_name: country.json.name,
        indicator_code: indicator,
        page: 1,
        per_page: 1000
      }
    });
  });
});

return results;

// Normalize World Bank indicator data to Basin 9-column schema
const items = $input.all();
const basinEvents = [];

items.forEach(item => {
  const data = item.json;

  // Extract country and indicator info from the nested structure
  const countryCode = data[1]?.iso2Code || 'unknown';
  const countryName = data[1]?.name || 'Unknown Country';
  const indicatorCode = data[2]?.indicator?.id || 'unknown';
  const indicatorName = data[2]?.indicator?.value || indicatorCode;

  // Process data points
  if (Array.isArray(data[1]) && data[1].length > 0) {
    data[1].forEach(record => {
      const year = record.date || 'unknown';
      const value = record.value !== null ? record.value : 'N/A';

      // Create deterministic event_id
      const eventId = `src_worldbank_${indicatorCode}_${countryCode}_${year}`;

      basinEvents.push({
        json: {
          id: eventId,
          event_id: eventId,
          source_id: 'src_worldbank',
          publisher: 'World Bank',
          headline: `${indicatorName} (${countryName})`,
          product: 'ops',
          tenant_id: 'shared',
          workspace_id: 'shared',
          captured_at: new Date().toISOString(),
          data: {
            indicator_code: indicatorCode,
            indicator_name: indicatorName,
            country_code: countryCode,
            country_name: countryName,
            year: year,
            value: value,
            unit: indicatorCode.includes('GDP') ? 'USD' : 
                  indicatorCode.includes('POP') ? 'people' : 
                  'percent'
          },
          provenance: {
            source_url: `https://api.worldbank.org/v2/country/${countryCode}/indicator/${indicatorCode}?format=json&date=${year}`,
            retrieved_at: new Date().toISOString(),
            api_version: 'v2',
            pagination: {
              page: 1,
              per_page: 1000
            }
          }
        }
      });
    });
  }
});

return basinEvents;

// Log successful ingestion to error tracking table
const workflowId = 'worldbank-v2';
const executionId = $execution.id;
const sourceId = 'src_worldbank';
const successCount = $input.all().length;

// Log to OpenObserve via HTTP
const logPayload = {
  timestamp: new Date().toISOString(),
  level: 'info',
  service: 'n8n',
  workflow_id: workflowId,
  execution_id: executionId,
  source_id: sourceId,
  message: `WorldBank ingestion batch completed`,
  metrics: {
    rows_processed: successCount,
    rows_per_second: successCount / 30
  },
  correlation_id: executionId
};

// In production, this would POST to OpenObserve endpoint
// For now, we'll just return the count

return [{ json: { success: true, count: successCount } }];

// Error handling trigger
const error = $input.first().json;
const workflowId = 'worldbank-v2';
const executionId = $execution.id;
const errorMessage = error.error?.message || JSON.stringify(error);

// Log error to connector_errors table
return [{
  json: {
    workflow_id: workflowId,
    workflow_name: 'Harvy — worldbank Ingestion v2',
    execution_id: executionId,
    error_message: errorMessage,
    error_type: error.error?.name || 'unknown',
    occurred_at: new Date().toISOString(),
    severity: 'high',
    context: {
      source: 'World Bank API',
      endpoint: error.error?.url || 'unknown'
    }
  }
}];

// Log error to OpenObserve
const error = $input.first().json;

// In production: POST to OpenObserve endpoint with error details
// For tracking: return structured error log

return [{
  json: {
    error_logged: true,
    workflow_id: 'worldbank-v2',
    execution_id: $execution.id,
    error: error.error_message || 'Unknown error',
    timestamp: new Date().toISOString()
  }
}];
